using UnityEngine;using UnityEngine.UI;
public sealed partial class TrainingOverlay {
 GameObject inputOptions;TrainingInputConfig inputOptionsConfig;InputField[] bindingFields=new InputField[20];Text inputBindingStatus;
 public bool OptionInputSettingsVisible{get;private set;}
 void CreateInputOptions(){inputOptionsConfig=TrainingInputConfig.Runtime(Resources.Load<TrainingInputConfig>("TrainingInputConfig"));if(inputOptionsConfig==null||inputOptionsConfig.layoutVersion<3)return;OptionButton("NavDummy","ダミー設定",optionPanel,()=>ShowInputOptions(false));OptionButton("NavInputs","入力設定",optionPanel,()=>ShowInputOptions(true));inputOptions=OptionObject("InputSettings",optionPanel);OptionText("Header","ABCJKLXYZ / Mania / runtime draft",inputOptions.transform,15);
  string[] labels={"A key","B key","C key","X key","Y key","Z key","J key ","K key ","L key ","A pad","B pad","C pad","X pad","Y pad","Z pad","J pad ","K pad ","L pad ","T1 modifier","T2 modifier (optional)"};
  for(int i=0;i<20;i++){OptionText("BindLabel"+i,labels[i],inputOptions.transform,12);var go=OptionObject("BindField"+i,inputOptions.transform);go.AddComponent<Image>().color=new Color(.11f,.16f,.18f);var field=go.AddComponent<TrainingOptionInputField>();field.characterLimit=128;field.lineType=InputField.LineType.SingleLine;field.shouldActivateOnSelect=false;var text=OptionText("Text","",go.transform,12);text.rectTransform.anchorMin=Vector2.zero;text.rectTransform.anchorMax=Vector2.one;text.rectTransform.offsetMin=new Vector2(5,2);text.rectTransform.offsetMax=new Vector2(-5,-2);field.textComponent=text;bindingFields[i]=field;}
  OptionButton("ApplyBindings","Apply runtime draft",inputOptions.transform,ApplyInputBindings);OptionButton("ReloadBindings","Discard draft",inputOptions.transform,ReadInputBindings);inputBindingStatus=OptionText("InputStatus","",inputOptions.transform,12);OptionText("InputNote","InputSystem control paths. Apply validates modifiers.\nRuntime only: no disk save / interactive rebinding yet.\nH Hold | ; TRC | Shift Mania | Space Dash\nR Record | P Play | Ctrl Reset | Esc/Options menu\nNo simultaneous-input wait. ABC = D1/D2/D3 (moves unassigned). Pad ABC via T1+JKL; direct paths below are separate. Modifier table is Inspector data.",inputOptions.transform,12);ReadInputBindings();ShowInputOptions(false);
 }
 void ReadInputBindings(){if(inputOptionsConfig==null)return;var keys=inputOptionsConfig.SlotKeys(false);for(int i=0;i<9;i++){bindingFields[i].SetTextWithoutNotify(keys[i]);bindingFields[i+9].SetTextWithoutNotify(inputOptionsConfig.slotGamepadBindings[i]);}bindingFields[18].SetTextWithoutNotify(inputOptionsConfig.modifier1Binding);bindingFields[19].SetTextWithoutNotify(inputOptionsConfig.modifier2Binding);if(inputBindingStatus!=null)inputBindingStatus.text="Draft not saved to disk";}
 public bool TryApplyInputBindings(string[] keys,string[] pad,string t1,string t2,out string error){error=null;if(keys==null||keys.Length!=9||pad==null||pad.Length!=9){error="Nine key and pad paths required";return false;}var trial=Instantiate(inputOptionsConfig);trial.slotKeyboardBindings=(string[])keys.Clone();trial.slotGamepadBindings=(string[])pad.Clone();trial.modifier1Binding=t1;trial.modifier2Binding=t2;if(!trial.ValidateV3(out error)){Destroy(trial);return false;}inputOptionsConfig.slotKeyboardBindings=(string[])keys.Clone();inputOptionsConfig.slotGamepadBindings=(string[])pad.Clone();inputOptionsConfig.modifier1Binding=t1;inputOptionsConfig.modifier2Binding=t2;Destroy(trial);player.GetComponent<TrainingControls>()?.ReloadBindings();player.opponent.GetComponent<TrainingSecondPlayerControls>()?.ReloadBindings();return true;}
 void ApplyInputBindings(){var keys=new string[9];var pad=new string[9];for(int i=0;i<9;i++){keys[i]=bindingFields[i].text.Trim();pad[i]=bindingFields[i+9].text.Trim();}inputBindingStatus.text=TryApplyInputBindings(keys,pad,bindingFields[18].text.Trim(),bindingFields[19].text.Trim(),out var error)?"Applied runtime draft; no disk save":error;}
 public void ShowInputOptions(bool visible){ShowTrainingOptions(false);ShowComparisonOptions(false);ShowLocomotionOptions(false);if(inputOptions==null)return;OptionInputSettingsVisible=visible;foreach(Transform child in optionPanel){if(child.name=="Title"||child.name=="Close"||child.name=="Pause"||child.name=="NavDummy"||child.name=="NavInputs"||child.name=="InputSettings"||child.name=="NavLocomotion"||child.name=="LocomotionSettings"||child.name=="NavComparison"||child.name=="ComparisonSettings"||child.name=="NavTraining"||child.name=="TrainingSettings")continue;child.gameObject.SetActive(!visible&&child.name!="Navigation");}inputOptions.SetActive(visible);RefreshInputOptions();}


 void RefreshInputOptions(){}
 void LayoutInputOptions(float w,float h,float left,float x,float right){if(inputOptions==null)return;OptionPlace((RectTransform)optionPanel.Find("NavDummy"),18,62,left-24,32);OptionPlace((RectTransform)optionPanel.Find("NavInputs"),18,101,left-24,32);OptionPlace((RectTransform)inputOptions.transform,x,62,right,h-112);OptionPlace((RectTransform)inputOptions.transform.Find("Header"),0,0,right,26);float col=right/2;for(int i=0;i<20;i++){int row=i<18?System.Array.IndexOf(CharacterAttackSlot.DisplayOrder,(BattleAttackSlot)(i%9)):9;int column=i<9?0:i<18?1:i-18;OptionPlace((RectTransform)inputOptions.transform.Find("BindLabel"+i),column*col,32+row*36,col-10,16);OptionPlace((RectTransform)bindingFields[i].transform,column*col,49+row*36,col-10,28);}OptionPlace((RectTransform)inputOptions.transform.Find("ApplyBindings"),0,400,col-10,30);OptionPlace((RectTransform)inputOptions.transform.Find("ReloadBindings"),col,400,col-10,30);OptionPlace(inputBindingStatus.rectTransform,0,436,right,30);OptionPlace((RectTransform)inputOptions.transform.Find("InputNote"),0,470,right,110);}
}
